import React, { useState } from 'react';

const MainSection = ({ onYes }) => {
  const [hoveredCard, setHoveredCard] = useState(null);

  const reasons = [
    {
      id: 1,
      icon: '✨',
      title: 'You Make Me Smile',
      description: 'Every moment with you lights up my world',
      position: 'top-[15%] left-[10%]',
      rotation: '-6deg',
    },
    {
      id: 2,
      icon: '❤️',
      title: 'You\'re My Safe Place',
      description: 'In your arms, I find my home',
      position: 'top-[10%] right-[15%]',
      rotation: '8deg',
    },
    {
      id: 3,
      icon: '🏰',
      title: 'You\'re My Forever',
      description: 'With you, I see eternity',
      position: 'top-[55%] left-[8%]',
      rotation: '4deg',
    },
    {
      id: 4,
      icon: '🔐',
      title: 'You\'re My Anchor',
      description: 'Steadfast and true',
      position: 'bottom-[20%] left-[15%]',
      rotation: '-5deg',
    },
    {
      id: 5,
      icon: '💫',
      title: 'You Complete Me',
      description: 'The missing piece of my heart',
      position: 'bottom-[15%] right-[10%]',
      rotation: '7deg',
    },
    {
      id: 6,
      icon: '🐝',
      title: 'You\'re Amazing',
      description: 'High integrity, high quality human',
      position: 'top-[55%] right-[12%]',
      rotation: '-4deg',
    },
  ];

  const decorativeElements = [
    { id: 1, position: 'top-[25%] left-[35%]', rotation: '45deg', color: 'from-fire-red to-crimson-light' },
    { id: 2, position: 'top-[20%] right-[30%]', rotation: '-30deg', color: 'from-glow-red to-fire-red' },
    { id: 3, position: 'bottom-[30%] left-[40%]', rotation: '120deg', color: 'from-crimson to-rose-red' },
    { id: 4, position: 'bottom-[25%] right-[35%]', rotation: '-60deg', color: 'from-fire-red to-crimson' },
  ];

  return (
    <div className="relative w-full min-h-screen flex items-center justify-center overflow-hidden px-4 py-16">
      {/* Decorative triangular elements */}
      {decorativeElements.map((elem) => (
        <div
          key={elem.id}
          className={`absolute w-16 h-16 md:w-20 md:h-20 opacity-40 animate-float`}
          style={{
            clipPath: 'polygon(50% 0%, 0% 100%, 100% 100%)',
            transform: `rotate(${elem.rotation})`,
          }}
        >
          <div className={`w-full h-full bg-gradient-to-br ${elem.color}`} style={{ top: elem.position, left: elem.position }}></div>
        </div>
      ))}

      {/* Floating cards */}
      {reasons.map((reason) => (
        <div
          key={reason.id}
          className={`absolute hidden md:block ${reason.position} animate-float-3d`}
          style={{
            transform: `rotate(${reason.rotation})`,
            animationDelay: `${reason.id * 0.3}s`,
          }}
          onMouseEnter={() => setHoveredCard(reason.id)}
          onMouseLeave={() => setHoveredCard(null)}
        >
          <div
            className={`glass p-6 rounded-2xl shadow-xl transition-all duration-500 cursor-pointer w-64 ${
              hoveredCard === reason.id ? 'scale-110 rotate-0 glow-box' : ''
            }`}
          >
            <div className="flex items-start gap-3">
              <div className="text-3xl drop-shadow-lg">{reason.icon}</div>
              <div>
                <h3 className="font-bold text-crimson-dark mb-1 text-sm">{reason.title}</h3>
                <p className="text-xs text-gray-600">{reason.description}</p>
              </div>
            </div>
          </div>
        </div>
      ))}

      {/* Central main question */}
      <div className="text-center z-10 max-w-4xl px-4">
        <div className="mb-8">
          <h1 className="text-5xl md:text-7xl lg:text-8xl font-black mb-4 leading-tight">
            <span className="block text-gray-800 drop-shadow-lg">WE LOVE</span>
            <span className="block gradient-text animate-glow-pulse text-6xl md:text-8xl lg:text-9xl my-2">
              BEING
            </span>
            <span className="block text-gray-800 drop-shadow-lg">WITH SOMEONE</span>
            <span className="block text-gray-900 mt-2">WHO IS 💙</span>
          </h1>
        </div>

        {/* Mobile cards grid */}
        <div className="md:hidden grid grid-cols-2 gap-4 mb-8">
          {reasons.map((reason) => (
            <div key={reason.id} className="glass p-4 rounded-xl shadow-lg glow-box">
              <div className="text-2xl mb-2">{reason.icon}</div>
              <h3 className="font-bold text-crimson-dark text-sm mb-1">{reason.title}</h3>
              <p className="text-xs text-gray-600">{reason.description}</p>
            </div>
          ))}
        </div>

        {/* Big question */}
        <div className="glass p-8 md:p-12 rounded-3xl shadow-2xl glow-box mt-12 animate-slide-up">
          <h2 className="text-3xl md:text-5xl font-bold mb-6 text-crimson-dark">
            So… will you be my <span className="gradient-text">Valentine?</span>
          </h2>

          <div className="flex gap-4 justify-center flex-col md:flex-row">
            <button
              onClick={onYes}
              className="px-10 py-5 bg-gradient-to-r from-crimson-light via-fire-red to-glow-red text-white font-bold text-xl rounded-full shadow-xl hover:shadow-2xl hover:scale-110 active:scale-95 transition-all duration-300 animate-bounce-soft glow-box"
            >
              Yes! 💙
            </button>

            <button
              onClick={onYes}
              className="px-10 py-5 bg-white border-2 border-crimson-dark text-crimson-dark font-bold text-xl rounded-full shadow-lg hover:shadow-xl hover:bg-red-100 hover:scale-105 active:scale-95 transition-all duration-300 glow-box"
            >
              Of course! 😌
            </button>
          </div>

          <p className="text-gray-600 mt-8 italic text-sm">
            Spoiler: Both answers lead to the same happy ending 💕
          </p>
        </div>

        {/* Footer */}
        <p className="mt-8 text-gray-600 text-sm font-medium">
          Made with 💙 on passion and love
        </p>
      </div>
    </div>
  );
};

export default MainSection;
